UPDATE proc_po_lines AS t SET expected_delivery_date = COALESCE(t.expected_delivery_date, '[]'::json), expected_dispatch_date = COALESCE(t.expected_dispatch_date, '[]'::json) WHERE (t.expected_delivery_date::text IS DISTINCT FROM (COALESCE(t.expected_delivery_date, '[]'::json))::text OR t.expected_dispatch_date::text IS DISTINCT FROM (COALESCE(t.expected_dispatch_date, '[]'::json))::text);
